import { h } from 'preact';
import PropTypes from 'prop-types';
import { isLowContrast } from '../utilities/color/contrastValidator';

const HEX_COLOR = /^#[0-9a-f]{6}$/i;

/**
 * Warns when a text color and background color are hard to read together.
 * Renders nothing when the contrast ratio meets WCAG AA for normal text (4.5:1).
 *
 * @param {string} props.textColor Six-digit hex color, e.g. "#1a2b3c"
 * @param {string} props.backgroundColor Six-digit hex color, e.g. "#ffffff"
 */
export const ColorContrastWarning = ({ textColor, backgroundColor }) => {
  // isLowContrast throws on malformed input, so skip the check rather than crash the render
  if (
    !HEX_COLOR.test(textColor) ||
    !HEX_COLOR.test(backgroundColor) ||
    !isLowContrast(textColor, backgroundColor, 4.5)
  ) {
    return null;
  }

  return (
    <p className="color-base-70 fs-s">These colors are hard to read together</p>
  );
};

