import { h } from 'preact';
import PropTypes from 'prop-types';

// WCAG AA minimum contrast ratio for normal text
const MIN_CONTRAST_RATIO = 4.5;

const channelToLinear = (channel) => {
  const srgb = channel / 255;
  return srgb <= 0.03928 ? srgb / 12.92 : ((srgb + 0.055) / 1.055) ** 2.4;
};

const relativeLuminance = (hex) => {
  const value = parseInt(hex.slice(1), 16);
  const red = channelToLinear((value >> 16) & 0xff);
  const green = channelToLinear((value >> 8) & 0xff);
  const blue = channelToLinear(value & 0xff);

  return 0.2126 * red + 0.7152 * green + 0.0722 * blue;
};

/**
 * Warns when the text and background colors have too little contrast to read comfortably
 * @param {string} props.textColor A six-digit hex color, e.g. "#1a2b3c"
 * @param {string} props.backgroundColor A six-digit hex color, e.g. "#ffffff"
 *
 * @returns A short warning when the contrast ratio is below 4.5:1, otherwise nothing.
 */
export const ColorContrastWarning = ({ textColor, backgroundColor }) => {
  const textLuminance = relativeLuminance(textColor);
  const backgroundLuminance = relativeLuminance(backgroundColor);
  const lighter = Math.max(textLuminance, backgroundLuminance);
  const darker = Math.min(textLuminance, backgroundLuminance);
  const contrastRatio = (lighter + 0.05) / (darker + 0.05);

  if (contrastRatio >= MIN_CONTRAST_RATIO) {
    return null;
  }

  return (
    <p className="color-accent-danger text-xs" role="alert">
      These colors are hard to read together
    </p>
  );
};

