import PropTypes from 'prop-types';

// WCAG AA minimum contrast ratio for normal text
const MIN_CONTRAST_RATIO = 4.5;

/**
 * Relative luminance of a six-digit hex color, per WCAG 2.x
 * @param {string} hex e.g. "#1a2b3c"
 */
const relativeLuminance = (hex) => {
  const [r, g, b] = [1, 3, 5].map((offset) => {
    const value = parseInt(hex.substr(offset, 2), 16) / 255;
    return value <= 0.03928 ? value / 12.92 : ((value + 0.055) / 1.055) ** 2.4;
  });

  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
};

const contrastRatio = (colorA, colorB) => {
  const [lighter, darker] = [
    relativeLuminance(colorA),
    relativeLuminance(colorB),
  ].sort((a, b) => b - a);

  return (lighter + 0.05) / (darker + 0.05);
};

/**
 * Warns when the text and background colors are too low-contrast to read comfortably
 * @param {string} props.textColor Six-digit hex text color, e.g. "#1a2b3c"
 * @param {string} props.backgroundColor Six-digit hex background color
 *
 * @returns A short warning, or nothing when the colors meet WCAG AA contrast
 */
export const ColorContrastWarning = ({ textColor, backgroundColor }) => {
  if (contrastRatio(textColor, backgroundColor) >= MIN_CONTRAST_RATIO) {
    return null;
  }

  return (
    <p className="color-accent-danger">
      These colors are hard to read together
    </p>
  );
};

