// WCAG AA minimum contrast ratio for normal text
const MIN_CONTRAST_RATIO = 4.5;

const relativeLuminance = (hex) => {
  const [r, g, b] = [1, 3, 5].map((i) => {
    const channel = parseInt(hex.slice(i, i + 2), 16) / 255;
    return channel <= 0.04045
      ? channel / 12.92
      : ((channel + 0.055) / 1.055) ** 2.4;
  });
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
};

const contrastRatio = (hexA, hexB) => {
  const [lighter, darker] = [
    relativeLuminance(hexA),
    relativeLuminance(hexB),
  ].sort((a, b) => b - a);
  return (lighter + 0.05) / (darker + 0.05);
};

/**
 * Renders a warning when the given text and background colors don't meet
 * the WCAG AA contrast ratio for normal text.
 * @param {string} props.textColor Six-digit hex color, e.g. "#1a2b3c"
 * @param {string} props.backgroundColor Six-digit hex color, e.g. "#ffffff"
 */
export const ColorContrastWarning = ({ textColor, backgroundColor }) => {
  if (contrastRatio(textColor, backgroundColor) >= MIN_CONTRAST_RATIO) {
    return null;
  }

  return (
    <p className="crayons-notice crayons-notice--warning" role="status">
      These colors are hard to read together
    </p>
  );
};

